/* This feature's own keyframes (prefix tour-, see pattern.md "A new movement") */
/* None: Pesquisa uses the shared vocabulary only. Its own pieces follow. */

/* Filter chip; the selected one uses the pattern's "selected item" tokens */
.chip {
  display: inline-flex;
  align-items: center;
  height: 26px;
  padding: 0 10px;
  border-radius: 9999px;
  border: 1px solid var(--color-neutral-5);
  background: var(--color-neutral-1);
  color: var(--color-neutral-10);
  font-size: 11px;
  font-weight: 500;
  white-space: nowrap;
}
.chip-on {
  border-color: var(--color-sky-4);
  background: var(--color-sky-1);
  color: var(--color-sky-10);
  box-shadow: 0 0 0 3px rgba(106, 151, 235, 0.15);
}
/* Result row: one process or document */
.result {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 6px 10px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-neutral-5);
  background: var(--color-neutral-1);
}
.ok {
  background: var(--color-success-2);
  color: var(--color-success-9);
}
